mapper.sql:
FROM achievement a LEFT JOIN canonical_entity_link achievement_link ON achievement_link.entity_type = 'ACHIEVEMENT' AND achievement_link.entity_id = a.id LEFT JOIN manual_field_override title_override ON title_override.achievement_id = a.id AND title_override.field_name = 'title' AND title_override.active = TRUE LEFT JOIN manual_field_override type_override ON type_override.achievement_id = a.id AND type_override.field_name = 'type' AND type_override.active = TRUE LEFT JOIN manual_field_override language_override ON language_override.achievement_id = a.id AND language_override.field_name = 'language' AND language_override.active = TRUE LEFT JOIN manual_field_override date_override ON date_override.achievement_id = a.id AND date_override.field_name = 'publicationDate' AND date_override.active = TRUE LEFT JOIN manual_field_override venue_override ON venue_override.achievement_id = a.id AND venue_override.field_name = 'venueId' AND venue_override.active = TRUE LEFT JOIN venue effective_venue ON effective_venue.id = COALESCE( CAST(JSON_UNQUOTE(venue_override.field_value) AS UNSIGNED), a.primary_venue_id) LEFT JOIN canonical_entity_link venue_link ON venue_link.entity_type = 'VENUE' AND venue_link.entity_id = effective_venue.id LEFT JOIN venue canonical_venue ON canonical_venue.id = COALESCE(venue_link.canonical_entity_id, effective_venue.id)
AND achievement_link.entity_id IS NULL
AND LOCATE( LOWER(#{filter.title}), LOWER(COALESCE(JSON_UNQUOTE(title_override.field_value), a.title_original, a.title_normalized)) ) > 0
AND EXISTS ( SELECT 1 FROM achievement_author relation_value LEFT JOIN canonical_entity_link relation_achievement_link ON relation_achievement_link.entity_type = 'ACHIEVEMENT' AND relation_achievement_link.entity_id = relation_value.achievement_id LEFT JOIN canonical_entity_link author_link ON author_link.entity_type = 'AUTHOR' AND author_link.entity_id = relation_value.author_id WHERE COALESCE( relation_achievement_link.canonical_entity_id, relation_value.achievement_id) = a.id AND COALESCE(author_link.canonical_entity_id, relation_value.author_id) = #{filter.authorId} )
AND EXISTS ( SELECT 1 FROM authorship_organization relation_value LEFT JOIN canonical_entity_link relation_achievement_link ON relation_achievement_link.entity_type = 'ACHIEVEMENT' AND relation_achievement_link.entity_id = relation_value.achievement_id LEFT JOIN canonical_entity_link organization_link ON organization_link.entity_type = 'ORGANIZATION' AND organization_link.entity_id = relation_value.organization_id WHERE COALESCE( relation_achievement_link.canonical_entity_id, relation_value.achievement_id) = a.id AND COALESCE( organization_link.canonical_entity_id, relation_value.organization_id) = #{filter.organizationId} )
AND YEAR(COALESCE( STR_TO_DATE(JSON_UNQUOTE(date_override.field_value), '%Y-%m-%d'), a.publication_date)) >= #{filter.publicationYearFrom}
AND YEAR(COALESCE( STR_TO_DATE(JSON_UNQUOTE(date_override.field_value), '%Y-%m-%d'), a.publication_date)) <= #{filter.publicationYearTo}
AND COALESCE(JSON_UNQUOTE(type_override.field_value), a.achievement_type) = #{filter.achievementType}
AND EXISTS ( SELECT 1 FROM achievement_source relation_value JOIN data_source source_value ON source_value.id = relation_value.source_id LEFT JOIN canonical_entity_link relation_achievement_link ON relation_achievement_link.entity_type = 'ACHIEVEMENT' AND relation_achievement_link.entity_id = relation_value.achievement_id WHERE COALESCE( relation_achievement_link.canonical_entity_id, relation_value.achievement_id) = a.id AND source_value.source_type = #{filter.sourceType} )
AND COALESCE(venue_link.canonical_entity_id, effective_venue.id) = #{filter.venueId}
AND EXISTS ( SELECT 1 FROM achievement_subject relation_value LEFT JOIN canonical_entity_link relation_achievement_link ON relation_achievement_link.entity_type = 'ACHIEVEMENT' AND relation_achievement_link.entity_id = relation_value.achievement_id WHERE COALESCE( relation_achievement_link.canonical_entity_id, relation_value.achievement_id) = a.id AND relation_value.subject_id = #{filter.topicId} )

mapper.select:
SELECT id FROM export_task WHERE status = 'PENDING'
ORDER BY created_at, id
LIMIT #{limit}

mapper.update:
UPDATE export_task
SET status = 'EXPIRED', version = version + 1
WHERE id = #{taskId} AND status = 'SUCCEEDED' AND expires_at <= #{expiredAt}
